using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Navigation;

namespace TodoBench;

public sealed partial class InnerPage : Page
{
    public InnerPage()
    {
        InitializeComponent();
    }

    protected override void OnNavigatedTo(NavigationEventArgs e)
    {
        InnerText.Text = $"inner {e.Parameter}";
    }

    private void OnNext(object sender, RoutedEventArgs e)
    {
        Frame.Navigate(typeof(InnerPage), "b");
    }
}

using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Navigation;

namespace TodoBench;

public sealed partial class DetailsPage : Page
{
    public DetailsPage()
    {
        InitializeComponent();
    }

    protected override void OnNavigatedTo(NavigationEventArgs e)
    {
        DetailsParam.Text = $"param {e.Parameter}";
    }

    private void OnBack(object sender, RoutedEventArgs e)
    {
        Frame.GoBack();
    }
}

    InitializeComponent();
    InnerFrame.Navigate(typeof(InnerPage), "a");
}

private void OnDetails(object sender, RoutedEventArgs e)
{
    Frame.Navigate(typeof(DetailsPage), "from-contacts");
}
